WITH exploded AS (SELECT id, created_at, coupon_codes, elem.product_id, elem.qty, elem.price, elem.promo FROM carts LATERAL VIEW EXPLODE(items) t AS elem) SELECT id, created_at, coupon_codes, product_id, qty, price, promo, ROUND(product_id / SUM(product_id) OVER (PARTITION BY promo), 4) AS product_id_share, ROUND(product_id / SUM(product_id) OVER (PARTITION BY promo), 4) AS product_id_share_2, COUNT(price) OVER (PARTITION BY promo ORDER BY CAST(created_at AS BIGINT) RANGE BETWEEN 1800 PRECEDING AND CURRENT ROW) AS price_count_30m FROM exploded;
